package runtime

import (
	"context"
	"crypto/sha256"
	"encoding/binary"
	"encoding/json"
	"fmt"
	"net/url"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"time"

	"github.com/cmetech/oscar-corrtest/internal/domain"
	"github.com/cmetech/oscar-corrtest/internal/oscar"
)

// This pair is generated by snmp-migration's H3C Smart Link mapping. Its two
// varbinds form the production alert key; the second carries our run identity.
const (
	trapMIBBase       = "1.3.6.1.4.1.25506.2.147"
	trapMappingName   = "1.3.6.1.4.1.25506.2.147.2"
	trapMappingSHA256 = "c189502a3a4ac3ed6ce26b24f4161b904bc82fa0c62a6c53c6684f2ae13856cc"
	trapProblemOID    = trapMappingName + ".0.3"
	trapClearOID      = trapMappingName + ".0.4"
	trapAlertName     = "hh3c_smlk_inactive_link_up_down"
	trapAlertGroup    = "hh3cSmlkInactiveLinkUpDown"
	trapAgent         = "HH3C-SMLK-MIB"
)

type TrapCheckOptions struct {
	Port int
}

type trapCheckReport struct {
	Coverage      map[string]string `json:"coverage"`
	RunID         string            `json:"runId"`
	Mapping       string            `json:"mapping"`
	MappingSHA256 string            `json:"mappingSha256"`
	AlertName     string            `json:"alertName"`
	RunToken      string            `json:"runToken"`
	AlertKey      string            `json:"alertKey"`
	HistoryID     string            `json:"historyId,omitempty"`
	Fingerprint   string            `json:"fingerprint,omitempty"`
	ProblemOID    string            `json:"problemOid"`
	ClearOID      string            `json:"clearOid"`
	Outcome       string            `json:"outcome"`
}

// StartTrapCheck starts one bounded SNMPv2c problem/clear test. The community
// is resolved from the process environment and never enters run evidence.
func (r *Runtime) StartTrapCheck(ctx context.Context, targetID string, options TrapCheckOptions) (domain.Run, error) {
	target, err := r.GetTarget(ctx, targetID)
	if err != nil {
		return domain.Run{}, err
	}
	if options.Port < 1 || options.Port > 65535 {
		return domain.Run{}, fmt.Errorf("trap port is invalid")
	}
	community := strings.TrimSpace(r.getenv("CORRTEST_SNMP_COMMUNITY"))
	if community == "" {
		return domain.Run{}, fmt.Errorf("trap community credential is unavailable")
	}
	if strings.ContainsAny(community, " \t\r\n") {
		return domain.Run{}, fmt.Errorf("trap community credential contains unsupported whitespace")
	}
	if _, err := exec.LookPath("snmptrap"); err != nil {
		return domain.Run{}, fmt.Errorf("snmptrap executable is required on the CorrTest host")
	}
	parsed, err := url.Parse(target.BaseURL)
	if err != nil || parsed.Hostname() == "" {
		return domain.Run{}, fmt.Errorf("target host is invalid")
	}
	client, err := r.newOSCARClient(target)
	if err != nil {
		return domain.Run{}, err
	}
	run, err := r.history.CreateRun(ctx, targetID, "", r.version)
	if err != nil {
		return domain.Run{}, err
	}
	executionCtx, cancel := context.WithCancel(r.rootCtx)
	r.activeMu.Lock()
	r.active[run.ID] = cancel
	r.activeMu.Unlock()
	r.runWG.Add(1)
	go func() {
		defer r.runWG.Done()
		defer func() {
			r.activeMu.Lock()
			delete(r.active, run.ID)
			r.activeMu.Unlock()
			cancel()
		}()
		r.runMu.Lock()
		defer r.runMu.Unlock()
		if err := r.executeTrapCheck(executionCtx, run, client, parsed.Hostname(), options.Port, community); err != nil {
			r.logger.Error("SNMP receiver check failed to persist", "run_id", run.ID, "error", err)
		}
	}()
	return run, nil
}

func (r *Runtime) executeTrapCheck(ctx context.Context, run domain.Run, client *oscar.Client, host string, port int, community string) error {
	stableCtx := context.WithoutCancel(ctx)
	now := func() time.Time { return time.Now().UTC() }
	transition := func(next domain.RunStatus, summary string) error {
		return r.database.TransitionRun(stableCtx, run.ID, next, now(), summary)
	}
	event := func(kind, summary string, detail any) error {
		body, _ := json.Marshal(detail)
		_, err := r.database.AppendRunEvent(stableCtx, domain.RunEvent{RunID: run.ID, Type: kind, Level: "info", OccurredAt: now(), Summary: summary, DetailJSON: string(body)})
		return err
	}
	report := trapCheckReport{RunID: run.ID, Mapping: trapMappingName, MappingSHA256: trapMappingSHA256,
		AlertName: trapAlertName, RunToken: run.ShortToken, ProblemOID: trapProblemOID, ClearOID: trapClearOID,
		Coverage: map[string]string{"inputPath": "snmp-trap", "receiverAdmission": "OBSERVED_IN_HISTORY_ONLY", "trapTransport": "UNACKNOWLEDGED_UDP", "notificationDelivery": "NOT_TESTED"}}
	digest := sha256.Sum256([]byte(run.ID))
	groupID := strconv.FormatUint(uint64(binary.BigEndian.Uint32(digest[:4])%256)+1, 10)
	ifIndex := strconv.FormatUint(uint64(binary.BigEndian.Uint32(digest[4:8])%0x7fffffff)+1, 10)
	// The migrated rule concatenates the first two numeric varbinds for alert_key.
	report.AlertKey = groupID + ifIndex
	if err := transition(domain.RunPreflight, "SNMP trap receiver preflight started"); err != nil {
		return err
	}
	plan, _ := json.Marshal(map[string]any{"runId": run.ID, "pattern": "trap-e2e", "inputPath": "snmp-trap", "mapping": trapMappingName, "mappingSha256": trapMappingSHA256,
		"problemOid": trapProblemOID, "clearOid": trapClearOID, "runToken": run.ShortToken, "alertKey": report.AlertKey, "targetHost": host, "port": port})
	if err := r.database.SetRunExecutionDocuments(stableCtx, run.ID, json.RawMessage(`{"inputPath":"snmp-trap"}`), plan, now()); err != nil {
		return err
	}
	if err := transition(domain.RunSettingUp, "Representative migrated mapping selected"); err != nil {
		return err
	}
	if err := transition(domain.RunInjecting, "Sending mapped H3C Smart Link problem trap"); err != nil {
		return err
	}
	if err := event("alert.prepared", "Problem trap recorded before UDP send", map[string]any{"oid": trapProblemOID, "runToken": run.ShortToken, "groupID": groupID, "ifIndex": ifIndex}); err != nil {
		return err
	}
	sentAt := now()
	problemErr := sendMappedTrap(ctx, host, port, community, trapProblemOID, groupID, ifIndex, run.ShortToken)
	if err := transition(domain.RunObserving, "Observing normalized Alert History"); err != nil {
		return err
	}
	var source oscar.HistoryRecord
	if problemErr == nil {
		source, _ = waitTrapHistory(ctx, client, report.AlertKey, sentAt, "firing", "", 60*time.Second)
	}
	if source.ID != "" {
		report.HistoryID, report.Fingerprint = source.ID, source.Fingerprint
		if err := event("alert.observed", "Mapped problem observed in Alert History", map[string]string{"historyId": source.ID, "fingerprint": source.Fingerprint}); err != nil {
			return err
		}
	}
	if err := transition(domain.RunAsserting, "Checking receiver mapping and lifecycle"); err != nil {
		return err
	}
	if err := transition(domain.RunCleaningUp, "Sending matching Smart Link clear trap"); err != nil {
		return err
	}
	// A clear is attempted even when the problem readback was uncertain; it cannot
	// turn an unobserved source into a clean result.
	if err := event("alert.prepared", "Clear trap recorded before UDP send", map[string]any{"oid": trapClearOID, "runToken": run.ShortToken, "groupID": groupID, "ifIndex": ifIndex}); err != nil {
		return err
	}
	clearCtx, cancel := context.WithTimeout(stableCtx, 10*time.Second)
	clearErr := sendMappedTrap(clearCtx, host, port, community, trapClearOID, groupID, ifIndex, run.ShortToken)
	cancel()
	verdict, cleanup := domain.VerdictInconclusive, domain.CleanupUnknown
	if problemErr != nil {
		report.Outcome = "problem trap local send failed; receiver outcome unknown"
	} else if source.ID == "" {
		report.Outcome = "problem trap not observed; receiver outcome unknown"
	} else if clearErr != nil {
		report.Outcome, verdict, cleanup = "clear trap local send failed", domain.VerdictFail, domain.CleanupDirty
	} else {
		resolved, _ := waitTrapHistory(ctx, client, report.AlertKey, sentAt, "resolved", source.ID, 60*time.Second)
		if resolved.ID == source.ID {
			report.Outcome, verdict, cleanup = "mapped problem and clear observed", domain.VerdictPass, domain.CleanupClean
		} else {
			report.Outcome, verdict, cleanup = "clear not observed on original history", domain.VerdictFail, domain.CleanupDirty
		}
	}
	if err := event("receiver.result", report.Outcome, map[string]any{"verdict": verdict, "cleanup": cleanup, "historyId": report.HistoryID}); err != nil {
		return err
	}
	encoded, _ := json.Marshal(report)
	return r.database.CompleteRun(stableCtx, run.ID, verdict, cleanup, encoded, "", now())
}

func sendMappedTrap(ctx context.Context, host string, port int, community, oid, groupID, ifIndex, token string) error {
	configDir, err := os.MkdirTemp("", "corrtest-snmp-")
	if err != nil {
		return fmt.Errorf("create private SNMP config: %w", err)
	}
	defer os.RemoveAll(configDir)
	if err := os.WriteFile(filepath.Join(configDir, "snmp.conf"), []byte("defCommunity "+community+"\n"), 0o600); err != nil {
		return fmt.Errorf("write private SNMP config: %w", err)
	}
	// Net-SNMP reads defCommunity from this private file; keep it out of argv and evidence.
	cmd := exec.CommandContext(ctx, "snmptrap", "-v", "2c",
		host+":"+strconv.Itoa(port), "", oid,
		trapMIBBase+".1.1.1.1."+groupID, "i", groupID,
		trapMIBBase+".1.2.1.1."+groupID+"."+ifIndex, "i", ifIndex,
		".1.3.6.1.2.1.2.2.1.2."+ifIndex, "s", "CorrTest "+token)
	cmd.Env = append(os.Environ(), "SNMPCONFPATH="+configDir)
	if err := cmd.Run(); err != nil {
		return fmt.Errorf("SNMP trap local send failed: %T", err)
	}
	return nil
}

func waitTrapHistory(ctx context.Context, client *oscar.Client, alertKey string, start time.Time, status, historyID string, limit time.Duration) (oscar.HistoryRecord, error) {
	deadline := time.NewTimer(limit)
	defer deadline.Stop()
	for {
		rows, err := client.FindHistory(ctx, oscar.HistoryQuery{AlertName: trapAlertName, Start: start.Add(-5 * time.Second), End: time.Now().UTC().Add(time.Minute)})
		if err == nil {
			for _, row := range rows {
				if row.Status != status || (historyID != "" && row.ID != historyID) ||
					row.Labels["alert_group"] != trapAlertGroup || row.Labels["agent"] != trapAgent ||
					row.Labels["alert_key"] != alertKey {
					continue
				}
				if status == "firing" && (row.Severity == nil || *row.Severity != "major") {
					continue
				}
				return row, nil
			}
		}
		select {
		case <-ctx.Done():
			return oscar.HistoryRecord{}, ctx.Err()
		case <-deadline.C:
			return oscar.HistoryRecord{}, fmt.Errorf("mapped trap not observed before deadline")
		case <-time.After(2 * time.Second):
		}
	}
}
